const require_defaults = require("../utils/defaults.js");
const require_index = require("../useSupported/index.js");
let react = require("react");
//#region src/useGeolocation/index.ts
const initCoord = {
	accuracy: 0,
	latitude: Number.POSITIVE_INFINITY,
	longitude: Number.POSITIVE_INFINITY,
	altitude: null,
	altitudeAccuracy: null,
	heading: null,
	speed: null,
	toJSON() {
		const { accuracy, latitude, longitude, altitude, altitudeAccuracy, heading, speed } = this;
		return {
			accuracy,
			latitude,
			longitude,
			altitude,
			altitudeAccuracy,
			heading,
			speed
		};
	}
};
const useGeolocation = (options = require_defaults.defaultOptions) => {
	const { enableHighAccuracy = true, maximumAge = 3e4, timeout = 27e3 } = options;
	const isSupported = require_index.useSupported(() => typeof navigator !== "undefined" && !!navigator.geolocation && typeof navigator.geolocation.getCurrentPosition === "function" && typeof navigator.geolocation.watchPosition === "function" && typeof navigator.geolocation.clearWatch === "function");
	const [coordinates, setCoordinates] = (0, react.useState)(initCoord);
	const [locatedAt, setLocatedAt] = (0, react.useState)(null);
	const [error, setError] = (0, react.useState)(null);
	const updatePosition = (0, react.useCallback)((position) => {
		setCoordinates(position.coords);
		setLocatedAt(position.timestamp);
		setError(null);
	}, []);
	const updateError = (0, react.useCallback)((err) => {
		setCoordinates(initCoord);
		setLocatedAt(null);
		setError(err);
	}, []);
	(0, react.useEffect)(() => {
		if (!isSupported) return;
		navigator.geolocation.getCurrentPosition(updatePosition, updateError);
		const watchId = navigator.geolocation.watchPosition(updatePosition, updateError, {
			enableHighAccuracy,
			maximumAge,
			timeout
		});
		return () => {
			if (watchId) navigator.geolocation.clearWatch(watchId);
		};
	}, [
		enableHighAccuracy,
		isSupported,
		maximumAge,
		timeout,
		updateError,
		updatePosition
	]);
	return {
		coordinates,
		locatedAt,
		error,
		isSupported
	};
};
//#endregion
exports.initCoord = initCoord;
exports.useGeolocation = useGeolocation;
